from 写入第二遍 import add
add('07_003',4,'16:9，武士头部侧面特写从画面右上伸入，眼缝贴近右侧轮廓，左侧大幅留云天；固定机位。','武士循着新来的声音转过头，白眼沿裂隙滑向董白的位置；他低低吐出第一声，头部再偏一点，第二句带着戏弄慢慢说完。厚重颈侧拉出一条弯线，转头到位后短短回摆，眼睛最终停在董白身上。','蓝灰天空占左侧与下方，深浅灰云层从左向右缓移。','上方冷白云天漫射，头部弧面浅灰、眼裂深黑。','厚重颈部转动的低响，缓慢鼻息与风声。',ja=['ほう。','また子猫が一匹、自分からやって来たか。'],tone='第一声意外兴味，第二句慢而轻佻，称呼带侮辱。',kind='mixed',phase='process',node={'武士.关注':'由青移向新来的董白'},meaning='武士转头看到董白，眼缝侧面和轻佻称呼保留；页外词义注不入对白。',characters=['鬼头武士'],card={'opening':'新增来者吸引武士。','beats':['白眼先移、头再转','颈侧回摆，戏弄的话落完'],'coupling':'转向先把攻击性的注意移给董白。','landing':'等待董白回应。'})
add('08_001',1.5,'16:9，董白下半张脸与高领肩线特写，笑口居画面中央，眼睛在画幅上缘以外；固定机位，两侧马尾发绺入框。','董白唇角扬高，轻轻把下巴往前送，短短应声；两肩先向内绷一小拍，发绺随即向两侧离开脸颊，胸前衣领被抻平，展开动作在下一镜继续。','发绺之间露出窄幅蓝灰天空，肩线外是浅灰云层。','上方冷白柔光照亮唇角与下巴，黑色高领保留软冷反光。','衣领随两肩收紧轻擦，发丝开始破风。',ja=['その通り。'],tone='董白笑着应声，语气自信，紧接着要把话接大。',kind='mixed',phase='anticipation',meaning='原格仅下半脸、笑口与肩线；自信答句接向下一夸张展开。',characters=['董白'])
add('08_002',4,'16:9，董白从头到膝的全景居画面中央，两臂向左右展开，双马尾高挑进入上方两角；稍低机位迅速后退，动作顶点停半拍。','董白把刚收拢的双肩猛地打开，两臂向两侧伸展，十指张开；双马尾先被头部上扬带起，再冲过头顶卷成两道长弧。她眼睛夸张化成亮白椭圆，嘴角展开成大笑，胸口挺起，一口气把自己说成猛虎；动作顶点膝盖仍稳，马尾在头顶回卷后坠下。','两侧蓝灰云层暂压成浅冷灰白的扩张图形底，纵向云带在人物后方扬起，下缘保留灰绿石铺地面。','冷白环境光统一，图形底略提亮，黑裙与黑发留清晰软亮边。','双臂展开一声衣料脆响，长马尾扬起的长风声接轻飘回落声。',ja=['でも、私はものすごく強い猛虎よ！'],tone='高声昂扬地夸耀，重音砸在“強い猛虎”，一口气挺到顶点。',kind='mixed',phase='peak',meaning='原格大幅张臂、夸张白眼、大笑与高扬马尾完整保留。',characters=['董白'],card={'opening':'董白把轻佻称呼反拿来抬高自己。','beats':['双肩猛开、张指挺胸','眼睛夸张变白，大笑自比猛虎','马尾冲顶后回卷'],'coupling':'夸耀重音和张臂顶点重合，长马尾延后收束。','landing':'保持得意站姿，等待认可。'})
